 Iată un obiect JSON valid care satisface schema dată:

```
{
  "properties": {
    "check_in_date": {
      "description": "Data dorită de check-in",
      "format": "date",
      "type": "string"
    },
    "check_out_date": {
      "description": "Data dorită de check-out",
      "format": "date",
      "type": "string"
    },
    "location": {
      "description": "Locația dorită a hotelului",
      "type": "string"
    },
    "price_range": {
      "properties": {
        "max": {
          "description": "Intervalul maxim de preț pe noapte",
          "type": "number"
        },
        "min": {
          "description": "Intervalul minim de preț pe noapte",
          "type": "number"
        }
      },
      "type": "object"
    }
