      "title": "Point",
      "type": "object",
      "description": "A point geometry object.",
      "example": "../examples/geometryObject.json",
      "translation": {
        "ISO 19115-2": [
          "EX_Extent > geographicElement > EX_BoundingPolygon > polygon > Point"
        ]
      },
      "properties": {
        "type": {
          "enum": [
            "Point"
          ],
