      "type": "object",
      "properties": {
        "release_date": {
          "type": "string",
          "format": "date-time"
        }
      }
    },
    "VRT": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z_]*$"
        },
        "type": {
          "type": "string",
          "enum": [
            "category",
            "subcategory",
            "variant"
          ]
        },
        "name": {
          "type": "string",
          "pattern": "^[ a-zA-Z0-9-+()/,.<]*$"
        },
        "priority": {
          "anyOf": [
            {
              "type": "number",
              "minimum": 1,
              "maximum": 5
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "id",
        "name",
        "type",
        "priority"
      ]
    },
    "VRTparent": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z_]*$"
        },
        "name": {
          "type": "string",
