          "type": "string",
          "enum": [
            "category",
            "subcategory"
          ]
        },
        "children": {
          "type": "array",
          "items": {
            "anyOf": [
              {
                "$ref": "#/definitions/VRTparent"
              },
              {
                "$ref": "#/definitions/VRT"
              }
            ]
          },
          "minItems": 1
        }
      },
      "required": [
        "id",
        "name",
        "type",
        "children"
      ]
    }
  },
  "type": "object",
  "required": [
    "metadata",
    "content"
  ],
  "properties": {
    "metadata": {
      "$ref": "#/definitions/VRTmetadata"
    },
    "content": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "$ref": "#/definitions/VRTparent"
          },
          {
            "$ref": "#/definitions/VRT"
          }
        ]
      }
    }
  }
}

